  67→+	"strings"
  68→+)
  69→+
  70→+const (
  71→+	// DefaultBaseURL is the production Entire API origin.
  72→+	DefaultBaseURL = "https://entire.io"
  73→+
  74→+	// BaseURLEnvVar overrides the Entire API origin for local development.
  75→+	BaseURLEnvVar = "ENTIRE_API_BASE_URL"
  76→+)
  77→+
  78→+// BaseURL returns the effective Entire API base URL.
  79→+// ENTIRE_API_BASE_URL takes precedence over the production default.
  80→+func BaseURL() string {
  81→+	if raw := strings.TrimSpace(os.Getenv(BaseURLEnvVar)); raw != "" {
  82→+		return normalizeBaseURL(raw)
  83→+	}
  84→+
  85→+	return DefaultBaseURL
  86→+}
  87→+
  88→+// ResolveURL joins an API-relative path against the effective base URL.
  89→+func ResolveURL(path string) (string, error) {
  90→+	return ResolveURLFromBase(BaseURL(), path)
  91→+}
  92→+
  93→+// ResolveURLFromBase joins an API-relative path against an explicit base URL.
  94→+func ResolveURLFromBase(baseURL, path string) (string, error) {
  95→+	base, err := url.Parse(baseURL)
  96→+	if err != nil {
  97→+		return "", fmt.Errorf("parse base URL: %w", err)
  98→+	}
  99→+
 100→+	rel, err := url.Parse(path)
 101→+	if err != nil {
 102→+		return "", fmt.Errorf("parse path: %w", err)
 103→+	}
 104→+
 105→+	return base.ResolveReference(rel).String(), nil
 106→+}
 107→+
 108→+func normalizeBaseURL(raw string) string {
 109→+	return strings.TrimRight(strings.TrimSpace(raw), "/")
 110→+}
