 46→func runLogin(ctx context.Context, outW, errW io.Writer, printBrowserURL bool) error {
 47→	client := auth.NewClient(nil)
 48→
 49→	start, err := client.StartDeviceAuth(ctx)
 50→	if err != nil {
 51→		return fmt.Errorf("start login: %w", err)
 52→	}
 53→
 54→	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
 55→	approvalURL := start.VerificationURIComplete
 56→	if approvalURL == "" {
 57→		approvalURL = start.VerificationURI
 58→	}
 59→
 60→	fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
 61→
 62→	if printBrowserURL {
 63→		fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 64→	} else {
 65→		if err := browserOpener(ctx, approvalURL); err != nil {
 66→			fmt.Fprintf(errW, "Warning: failed to open browser automatically: %v\n", err)
 67→			fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 68→		} else {
 69→			fmt.Fprintln(outW, "Opened your browser for approval.")
 70→		}
 71→	}
 72→
 73→	fmt.Fprintln(outW, "Waiting for approval...")
 74→
 75→	token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, start.Interval)
 76→	if err != nil {
 77→		return fmt.Errorf("complete login: %w", err)
 78→	}
 79→
 80→	store, err := auth.NewStore()
 81→	if err != nil {
 82→		return fmt.Errorf("create auth store: %w", err)
 83→	}
 84→
 85→	if err := store.SaveToken(client.BaseURL(), token); err != nil {
 86→		return fmt.Errorf("save auth token: %w", err)
 87→	}
 88→
 89→	fmt.Fprintf(outW, "Login complete. Saved token to %s\n", store.FilePath())
 90→	return nil
 91→}
