 93→func waitForApproval(ctx context.Context, poller deviceAuthPoller, deviceCode string, expiresIn, interval int) (string, error) {
 94→	expiry := time.Duration(expiresIn) * time.Second
 95→	if expiry <= 0 || expiry > maxExpiresIn {
 96→		expiry = maxExpiresIn
 97→	}
 98→	deadline := time.Now().Add(expiry)
 99→	pollInterval := time.Duration(interval) * time.Second
100→	if pollInterval <= 0 {
101→		pollInterval = fallbackDeviceAuthPollInterval
102→	}
103→
104→	consecutiveErrors := 0
105→
106→	for {
107→		if time.Now().After(deadline) {
108→			return "", errors.New("device authorization expired")
109→		}
110→
111→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
112→		if err != nil {
113→			consecutiveErrors++
114→			if consecutiveErrors >= maxTransientErrors {
115→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
116→			}
117→			// Transient error — wait and retry.
118→			select {
119→			case <-ctx.Done():
120→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
121→			case <-time.After(pollInterval):
122→			}
123→			continue
124→		}
125→		consecutiveErrors = 0
126→
127→		switch result.Error {
128→		case "", "authorization_pending":
129→			// continue below
130→		case "slow_down":
131→			pollInterval += slowDownBackoff
132→			if pollInterval > maxPollInterval {
133→				pollInterval = maxPollInterval
134→			}
135→		case "access_denied":
136→			return "", errors.New("device authorization denied")
137→		case "expired_token":
138→			return "", errors.New("device authorization expired")
139→		default:
140→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
141→		}
142→
143→		if result.Error == "" {
144→			if result.AccessToken == "" {
145→				return "", errors.New("device authorization completed without a token")
146→			}
147→			return result.AccessToken, nil
148→		}
149→
150→		select {
151→		case <-ctx.Done():
152→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
153→		case <-time.After(pollInterval):
154→		}
155→	}
156→}
