158→func openBrowser(ctx context.Context, browserURL string) error {
159→	u, err := url.Parse(browserURL)
160→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
161→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
162→	}
163→
164→	var command string
165→	var args []string
166→
167→	switch runtime.GOOS {
168→	case "darwin":
169→		command = "open"
170→		args = []string{browserURL}
171→	case "linux":
172→		command = "xdg-open"
173→		args = []string{browserURL}
174→	case "windows":
175→		command = "cmd"
176→		args = []string{"/c", "start", "", browserURL}
177→	default:
178→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
179→	}
180→
181→	cmd := exec.CommandContext(ctx, command, args...)
182→	if err := cmd.Start(); err != nil {
183→		return fmt.Errorf("start browser command %q: %w", command, err)
184→	}
185→
186→	if err := cmd.Process.Release(); err != nil {
187→		return fmt.Errorf("release browser process: %w", err)
188→	}
189→
190→	return nil
191→}
