 60→func (c *Client) StartDeviceAuth(ctx context.Context) (*DeviceAuthStart, error) {
 61→	endpoint, err := apiurl.ResolveURLFromBase(c.baseURL, "/oauth/device/code")
 62→	if err != nil {
 63→		return nil, fmt.Errorf("resolve device auth start URL: %w", err)
 64→	}
 65→
 66→	body := url.Values{}
 67→	body.Set("client_id", "entire-cli")
 68→	body.Set("scope", "cli")
 69→
 70→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, strings.NewReader(body.Encode()))
 71→	if err != nil {
 72→		return nil, fmt.Errorf("create device auth start request: %w", err)
 73→	}
 74→
 75→	req.Header.Set("Accept", "application/json")
 76→	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
 77→	req.Header.Set("User-Agent", "entire-cli")
 78→
 79→	resp, err := c.httpClient.Do(req) //nolint:gosec // base URL is constrained to Entire API or explicit local dev override
 80→	if err != nil {
 81→		return nil, fmt.Errorf("start device auth: %w", err)
 82→	}
 83→	defer resp.Body.Close()
 84→
 85→	if resp.StatusCode != http.StatusOK {
 86→		return nil, readAPIError(resp, "start device auth")
 87→	}
 88→
 89→	var result DeviceAuthStart
 90→	if err := decodeJSONStrict(resp.Body, &result); err != nil {
 91→		return nil, fmt.Errorf("decode device auth start response: %w", err)
 92→	}
 93→
 94→	return &result, nil
 95→}
