 97→func (c *Client) PollDeviceAuth(ctx context.Context, deviceCode string) (*DeviceAuthPoll, error) {
 98→	endpoint, err := apiurl.ResolveURLFromBase(c.baseURL, "/oauth/token")
 99→	if err != nil {
100→		return nil, fmt.Errorf("resolve device auth poll URL: %w", err)
101→	}
102→
103→	body := url.Values{}
104→	body.Set("grant_type", "urn:ietf:params:oauth:grant-type:device_code")
105→	body.Set("client_id", "entire-cli")
106→	body.Set("device_code", deviceCode)
107→
108→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, strings.NewReader(body.Encode()))
109→	if err != nil {
110→		return nil, fmt.Errorf("create device auth poll request: %w", err)
111→	}
112→
113→	req.Header.Set("Accept", "application/json")
114→	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
115→	req.Header.Set("User-Agent", "entire-cli")
116→
117→	resp, err := c.httpClient.Do(req) //nolint:gosec // base URL is constrained to Entire API or explicit local dev override
118→	if err != nil {
119→		return nil, fmt.Errorf("poll device auth: %w", err)
120→	}
121→	defer resp.Body.Close()
122→
123→	if resp.StatusCode != http.StatusOK {
124→		apiErr, err := readAPIErrorResponse(resp)
125→		if err != nil {
126→			return nil, fmt.Errorf("poll device auth: %w", err)
127→		}
128→		return &DeviceAuthPoll{Error: apiErr.Error}, nil
129→	}
130→
131→	var result DeviceAuthPoll
132→	if err := decodeJSON(resp.Body, &result); err != nil {
133→		return nil, fmt.Errorf("decode device auth poll response: %w", err)
134→	}
135→
136→	return &result, nil
137→}
138→
139→func readAPIErrorResponse(resp *http.Response) (*errorResponse, error) {
140→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
141→	if err != nil {
142→		return nil, fmt.Errorf("status %d", resp.StatusCode)
143→	}
144→
145→	var apiErr errorResponse
146→	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
147→		return &apiErr, nil
148→	}
149→
150→	text := strings.TrimSpace(string(body))
151→	if text != "" {
152→		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, text)
153→	}
154→
155→	return nil, fmt.Errorf("status %d", resp.StatusCode)
156→}
157→
158→func readAPIError(resp *http.Response, action string) error {
159→	apiErr, err := readAPIErrorResponse(resp)
160→	if err == nil {
161→		return fmt.Errorf("%s: %s", action, apiErr.Error)
162→	}
163→	return fmt.Errorf("%s: %w", action, err)
164→}
165→
166→func decodeJSON(r io.Reader, dest any) error {
167→	return decodeJSONWithOptions(r, dest, false)
168→}
169→
170→func decodeJSONStrict(r io.Reader, dest any) error {
171→	return decodeJSONWithOptions(r, dest, true)
172→}
173→
174→func decodeJSONWithOptions(r io.Reader, dest any, strict bool) error {
175→	body, err := io.ReadAll(io.LimitReader(r, maxResponseBytes))
176→	if err != nil {
177→		return fmt.Errorf("read JSON response: %w", err)
178→	}
179→
180→	dec := json.NewDecoder(bytes.NewReader(body))
181→	if strict {
182→		dec.DisallowUnknownFields()
183→	}
184→	if err := dec.Decode(dest); err != nil {
185→		return fmt.Errorf("decode JSON response: %w", err)
186→	}
187→
188→	return nil
189→}
