 47→func (s *Store) SaveToken(baseURL, token string) error {
 48→	if strings.TrimSpace(token) == "" {
 49→		return errors.New("refusing to save empty token")
 50→	}
 51→
 52→	state, err := s.Load()
 53→	if err != nil {
 54→		return err
 55→	}
 56→
 57→	if state.Tokens == nil {
 58→		state.Tokens = make(map[string]Token)
 59→	}
