 95→func (s *Store) save(state *File) error {
 96→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
 97→	if err != nil {
 98→		return fmt.Errorf("marshal auth file: %w", err)
 99→	}
100→
101→	dir := filepath.Dir(s.filePath)
102→	if err := os.MkdirAll(dir, 0o700); err != nil {
103→		return fmt.Errorf("create auth directory: %w", err)
104→	}
105→
106→	tmpPath := filepath.Join(dir, ".auth_tmp_"+strconv.FormatInt(time.Now().UnixNano(), 10))
107→	tmpFile, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600) //nolint:gosec // path is internally constructed from s.filePath
108→	if err != nil {
109→		return fmt.Errorf("create temp auth file: %w", err)
110→	}
111→	defer os.Remove(tmpFile.Name())
112→
113→	if _, err := tmpFile.Write(data); err != nil {
114→		_ = tmpFile.Close()
115→		return fmt.Errorf("write temp auth file: %w", err)
116→	}
117→
118→	if err := tmpFile.Sync(); err != nil {
119→		_ = tmpFile.Close()
120→		return fmt.Errorf("sync temp auth file: %w", err)
121→	}
122→
123→	if err := tmpFile.Close(); err != nil {
124→		return fmt.Errorf("close temp auth file: %w", err)
125→	}
126→
127→	if err := os.Rename(tmpFile.Name(), s.filePath); err != nil { //nolint:gosec // destination path is internally constructed or test-controlled
128→		return fmt.Errorf("rename auth file: %w", err)
129→	}
130→
131→	return nil
132→}
