 95→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
 96→	expiry := time.Duration(expiresIn) * time.Second
 97→	if expiry <= 0 || expiry > maxExpiresIn {
 98→		expiry = maxExpiresIn
 99→	}
100→	deadline := time.Now().Add(expiry)
101→	pollInterval := time.Duration(interval) * time.Second
102→	if pollInterval <= 0 {
103→		pollInterval = fallbackDeviceAuthPollInterval
104→	}
105→
106→	consecutiveErrors := 0
107→
108→	for {
109→		if time.Now().After(deadline) {
110→			return "", errors.New("device authorization expired")
111→		}
112→
113→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
114→		if err != nil {
115→			consecutiveErrors++
116→			if consecutiveErrors >= maxTransientErrors {
117→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
118→			}
119→			// Transient error — wait and retry.
120→			select {
121→			case <-ctx.Done():
122→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
123→			case <-time.After(pollInterval):
124→			}
125→			continue
126→		}
127→		consecutiveErrors = 0
128→
129→		switch result.Error {
130→		case "", "authorization_pending":
131→			// continue below
132→		case "slow_down":
133→			pollInterval += slowDownBackoff
134→			if pollInterval > maxPollInterval {
135→				pollInterval = maxPollInterval
136→			}
137→		case "access_denied":
138→			return "", errors.New("device authorization denied")
139→		case "expired_token":
140→			return "", errors.New("device authorization expired")
141→		default:
142→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
143→		}
144→
145→		if result.Error == "" {
146→			if result.AccessToken == "" {
147→				return "", errors.New("device authorization completed without a token")
148→			}
149→			return result.AccessToken, nil
150→		}
151→
152→		select {
153→		case <-ctx.Done():
154→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
155→		case <-time.After(pollInterval):
156→		}
157→	}
158→}
