160→func openBrowser(ctx context.Context, browserURL string) error {
161→	u, err := url.Parse(browserURL)
162→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
163→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
164→	}
165→
166→	var command string
167→	var args []string
168→
169→	switch runtime.GOOS {
170→	case "darwin":
171→		command = "open"
172→		args = []string{browserURL}
173→	case "linux":
174→		command = "xdg-open"
175→		args = []string{browserURL}
176→	case "windows":
177→		command = "cmd"
178→		args = []string{"/c", "start", "", browserURL}
179→	default:
180→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
181→	}
182→
183→	cmd := exec.CommandContext(ctx, command, args...)
184→	if err := cmd.Start(); err != nil {
