 63→// loadHostsData loads the hosts data from disk with file locking
 64→func loadHostsData(configDir string) (map[string]*HostInfo, error) {
 65→	path, err := getHostsFilePath(configDir)
 66→	if err != nil {
 67→		return nil, err
 68→	}
 69→
 70→	// Acquire exclusive lock for reading (flock doesn't support shared locks)
 71→	lockPath := path + ".lock"
 72→	fileLock := flock.New(lockPath)
 73→
 74→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
 75→	defer cancel()
