 95→			return make(map[string]*HostInfo), nil
 96→		}
 97→		return nil, fmt.Errorf("failed to read hosts file: %w", err)
 98→	}
 99→
100→	var hosts map[string]*HostInfo
101→	if err := json.Unmarshal(data, &hosts); err != nil {
102→		return nil, fmt.Errorf("failed to parse hosts file: %w", err)
103→	}
104→
