108→// saveHostsData saves the hosts data to disk with file locking and atomic writes
109→func saveHostsData(hosts map[string]*HostInfo, configDir string) error {
110→	path, err := getHostsFilePath(configDir)
111→	if err != nil {
112→		return err
113→	}
114→
115→	// Acquire exclusive lock for writing
116→	lockPath := path + ".lock"
117→	fileLock := flock.New(lockPath)
118→
119→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
120→	defer cancel()
121→
122→	locked, err := fileLock.TryLockContext(ctx, 100*time.Millisecond)
123→	if err != nil {
124→		return fmt.Errorf("failed to acquire lock: %w", err)
125→	}
126→	if !locked {
127→		return errors.New("timeout acquiring lock on hosts file")
128→	}
129→	defer func() {
130→		// Log unlock errors but don't fail the operation
131→		if unlockErr := fileLock.Unlock(); unlockErr != nil {
132→			fmt.Fprintf(os.Stderr, "Warning: failed to unlock hosts file: %v\n", unlockErr)
133→		}
134→	}()
135→
136→	data, err := json.MarshalIndent(hosts, "", "  ")
137→	if err != nil {
138→		return fmt.Errorf("failed to marshal hosts data: %w", err)
139→	}
140→
141→	// Atomic write: create temp file, write, fsync, rename
142→	tmpFile, err := os.CreateTemp(filepath.Dir(path), ".hosts.json.tmp.*")
143→	if err != nil {
144→		return fmt.Errorf("failed to create temp file: %w", err)
145→	}
146→	tmpPath := tmpFile.Name()
147→
148→	// Ensure cleanup of temp file on error
149→	defer func() {
150→		if tmpFile != nil {
151→			_ = tmpFile.Close()
152→			_ = os.Remove(tmpPath)
153→		}
154→	}()
155→
156→	// Write data to temp file
157→	if _, err := tmpFile.Write(data); err != nil {
158→		return fmt.Errorf("failed to write to temp file: %w", err)
159→	}
160→
161→	// Fsync to ensure data is written to disk
162→	if err := tmpFile.Sync(); err != nil {
163→		return fmt.Errorf("failed to sync temp file: %w", err)
164→	}
165→
166→	// Close the temp file
167→	if err := tmpFile.Close(); err != nil {
168→		return fmt.Errorf("failed to close temp file: %w", err)
169→	}
170→
171→	// Set proper permissions
172→	if err := os.Chmod(tmpPath, 0600); err != nil {
173→		return fmt.Errorf("failed to set permissions on temp file: %w", err)
174→	}
175→
176→	// Atomic rename
177→	if err := os.Rename(tmpPath, path); err != nil {
178→		return fmt.Errorf("failed to rename temp file: %w", err)
179→	}
180→
181→	// Clear tmpFile to prevent cleanup in defer
182→	tmpFile = nil
183→
184→	return nil
185→}
