493→func handleGet(configDir string) {
494→	scanner := bufio.NewScanner(os.Stdin)
495→
496→	var host string
497→	var username string
498→	for scanner.Scan() {
499→		line := scanner.Text()
500→		if line == "" {
501→			break
502→		}
503→		// Parse git credential input format: key=value
504→		if strings.HasPrefix(line, gitCredentialHostPrefix) {
505→			host = strings.TrimPrefix(line, gitCredentialHostPrefix)
506→		}
507→		if strings.HasPrefix(line, gitCredentialUsernamePrefix) {
508→			username = strings.TrimPrefix(line, gitCredentialUsernamePrefix)
509→		}
510→	}
511→
512→	if host == "" {
513→		fmt.Fprintf(os.Stderr, "Error: host not provided\n")
514→		os.Exit(1)
515→	}
516→
517→	// If username not provided by git, use the active user for this host
518→	if username == "" {
519→		activeUser, err := getActiveUser(host, configDir)
520→		if err != nil {
521→			fmt.Fprintf(os.Stderr, "Error: username not provided and could not get active user: %v\n", err)
522→			os.Exit(1)
523→		}
524→
525→		if activeUser == "" {
526→			fmt.Fprintf(os.Stderr, "Error: username not provided and no active user set for host %s\n", host)
527→			os.Exit(1)
528→		}
529→
530→		username = activeUser
531→	}
532→
533→	password, err := keyring.Get(getKeyringService(host), username)
534→	if err != nil {
535→		fmt.Fprintf(os.Stderr, "Error retrieving password from keyring: %v\n", err)
536→		os.Exit(1)
537→	}
538→
539→	fmt.Printf("username=%s\n", username)
540→	fmt.Printf("password=%s\n", password)
