119→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
120→			case <-time.After(pollInterval):
121→			}
122→			continue
123→		}
124→		consecutiveErrors = 0
125→
126→		switch result.Error {
127→		case "", "authorization_pending":
128→			// continue below
129→		case "slow_down":
130→			pollInterval += slowDownBackoff
131→			if pollInterval > maxPollInterval {
