1014→+func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
1015→+	expiry := time.Duration(expiresIn) * time.Second
1016→+	if expiry <= 0 || expiry > maxExpiresIn {
1017→+		expiry = maxExpiresIn
1018→+	}
1019→+	deadline := time.Now().Add(expiry)
1020→+	pollInterval := time.Duration(interval) * time.Second
1021→+	if pollInterval <= 0 {
1022→+		pollInterval = fallbackDeviceAuthPollInterval
1023→+	}
1024→+
1025→+	consecutiveErrors := 0
1026→+
1027→+	for {
1028→+		if time.Now().After(deadline) {
1029→+			return "", errors.New("device authorization expired")
1030→+		}
1031→+
1032→+		result, err := poller.PollDeviceAuth(ctx, deviceCode)
1033→+		if err != nil {
1034→+			consecutiveErrors++
1035→+			if consecutiveErrors >= maxTransientErrors {
1036→+				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
1037→+			}
1038→+			// Transient error — wait and retry.
1039→+			select {
1040→+			case <-ctx.Done():
1041→+				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
1042→+			case <-time.After(pollInterval):
1043→+			}
1044→+			continue
1045→+		}
1046→+		consecutiveErrors = 0
1047→+
1048→+		switch result.Error {
1049→+		case "", "authorization_pending":
1050→+			// continue below
1051→+		case "slow_down":
1052→+			pollInterval += slowDownBackoff
1053→+			if pollInterval > maxPollInterval {
1054→+				pollInterval = maxPollInterval
1055→+			}
1056→+		case "access_denied":
1057→+			return "", errors.New("device authorization denied")
1058→+		case "expired_token":
1059→+			return "", errors.New("device authorization expired")
1060→+		default:
1061→+			return "", fmt.Errorf("device authorization failed: %s", result.Error)
1062→+		}
1063→+
1064→+		if result.Error == "" {
1065→+			if result.AccessToken == "" {
1066→+				return "", errors.New("device authorization completed without a token")
1067→+			}
1068→+			return result.AccessToken, nil
1069→+		}
1070→+
1071→+		select {
1072→+		case <-ctx.Done():
1073→+			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
1074→+		case <-time.After(pollInterval):
1075→+		}
1076→+	}
1077→+}
