1079→+func openBrowser(ctx context.Context, browserURL string) error {
1080→+	u, err := url.Parse(browserURL)
1081→+	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
1082→+		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
1083→+	}
1084→+
1085→+	var command string
1086→+	var args []string
1087→+
1088→+	switch runtime.GOOS {
1089→+	case "darwin":
1090→+		command = "open"
1091→+		args = []string{browserURL}
1092→+	case "linux":
1093→+		command = "xdg-open"
1094→+		args = []string{browserURL}
1095→+	case "windows":
1096→+		command = "cmd"
1097→+		args = []string{"/c", "start", "", browserURL}
1098→+	default:
1099→+		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
1100→+	}
1101→+
1102→+	cmd := exec.CommandContext(ctx, command, args...)
1103→+	if err := cmd.Start(); err != nil {
1104→+		return fmt.Errorf("start browser command %q: %w", command, err)
1105→+	}
1106→+
1107→+	if err := cmd.Process.Release(); err != nil {
1108→+		return fmt.Errorf("release browser process: %w", err)
1109→+	}
1110→+
1111→+	return nil
1112→+}
