 48→func NewClient(httpClient *http.Client) *Client {
 49→	if httpClient == nil {
 50→		httpClient = &http.Client{}
 51→	}
 52→
 53→	return &Client{
 54→		httpClient: httpClient,
 55→		baseURL:    apiurl.BaseURL(),
 56→	}
