 63→func (c *Client) StartDeviceAuth(ctx context.Context) (*DeviceAuthStart, error) {
 64→	endpoint, err := apiurl.ResolveURLFromBase(c.baseURL, "/oauth/device/code")
 65→	if err != nil {
 66→		return nil, fmt.Errorf("resolve device auth start URL: %w", err)
 67→	}
 68→
 69→	body := url.Values{}
 70→	body.Set("client_id", clientID)
 71→	body.Set("scope", "cli")
 72→
 73→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, strings.NewReader(body.Encode()))
 74→	if err != nil {
 75→		return nil, fmt.Errorf("create device auth start request: %w", err)
 76→	}
 77→
 78→	req.Header.Set("Accept", "application/json")
 79→	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
 80→	req.Header.Set("User-Agent", "entire-cli")
 81→
 82→	resp, err := c.httpClient.Do(req) //nolint:gosec // base URL is constrained to Entire API or explicit local dev override
 83→	if err != nil {
 84→		return nil, fmt.Errorf("start device auth: %w", err)
 85→	}
 86→	defer resp.Body.Close()
 87→
 88→	if resp.StatusCode != http.StatusOK {
 89→		return nil, readAPIError(resp, "start device auth")
 90→	}
 91→
 92→	var result DeviceAuthStart
 93→	if err := decodeJSONStrict(resp.Body, &result); err != nil {
 94→		return nil, fmt.Errorf("decode device auth start response: %w", err)
 95→	}
 96→
 97→	return &result, nil
 98→}
 99→
100→func (c *Client) PollDeviceAuth(ctx context.Context, deviceCode string) (*DeviceAuthPoll, error) {
101→	endpoint, err := apiurl.ResolveURLFromBase(c.baseURL, "/oauth/token")
102→	if err != nil {
103→		return nil, fmt.Errorf("resolve device auth poll URL: %w", err)
104→	}
105→
106→	body := url.Values{}
107→	body.Set("grant_type", "urn:ietf:params:oauth:grant-type:device_code")
108→	body.Set("client_id", clientID)
109→	body.Set("device_code", deviceCode)
110→
111→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, strings.NewReader(body.Encode()))
112→	if err != nil {
113→		return nil, fmt.Errorf("create device auth poll request: %w", err)
114→	}
115→
116→	req.Header.Set("Accept", "application/json")
117→	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
118→	req.Header.Set("User-Agent", "entire-cli")
119→
120→	resp, err := c.httpClient.Do(req) //nolint:gosec // base URL is constrained to Entire API or explicit local dev override
121→	if err != nil {
122→		return nil, fmt.Errorf("poll device auth: %w", err)
123→	}
124→	defer resp.Body.Close()
125→
126→	if resp.StatusCode != http.StatusOK {
127→		apiErr, err := readAPIErrorResponse(resp)
128→		if err != nil {
129→			return nil, fmt.Errorf("poll device auth: %w", err)
130→		}
131→		return &DeviceAuthPoll{Error: apiErr.Error}, nil
132→	}
133→
134→	var result DeviceAuthPoll
135→	if err := decodeJSON(resp.Body, &result); err != nil {
136→		return nil, fmt.Errorf("decode device auth poll response: %w", err)
137→	}
138→
139→	return &result, nil
140→}
141→
142→func readAPIErrorResponse(resp *http.Response) (*errorResponse, error) {
143→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
144→	if err != nil {
145→		return nil, fmt.Errorf("status %d", resp.StatusCode)
146→	}
147→
148→	var apiErr errorResponse
149→	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
150→		return &apiErr, nil
151→	}
152→
153→	text := strings.TrimSpace(string(body))
154→	if text != "" {
155→		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, text)
156→	}
157→
158→	return nil, fmt.Errorf("status %d", resp.StatusCode)
159→}
160→
161→func readAPIError(resp *http.Response, action string) error {
162→	apiErr, err := readAPIErrorResponse(resp)
163→	if err == nil {
164→		return fmt.Errorf("%s: %s", action, apiErr.Error)
165→	}
166→	return fmt.Errorf("%s: %w", action, err)
167→}
168→
169→func decodeJSON(r io.Reader, dest any) error {
170→	return decodeJSONWithOptions(r, dest, false)
171→}
172→
173→func decodeJSONStrict(r io.Reader, dest any) error {
174→	return decodeJSONWithOptions(r, dest, true)
175→}
176→
177→func decodeJSONWithOptions(r io.Reader, dest any, strict bool) error {
178→	body, err := io.ReadAll(io.LimitReader(r, maxResponseBytes))
179→	if err != nil {
180→		return fmt.Errorf("read JSON response: %w", err)
181→	}
182→
183→	dec := json.NewDecoder(bytes.NewReader(body))
184→	if strict {
185→		dec.DisallowUnknownFields()
186→	}
187→	if err := dec.Decode(dest); err != nil {
188→		return fmt.Errorf("decode JSON response: %w", err)
189→	}
190→
191→	return nil
192→}
