 13→	"github.com/entireio/cli/cmd/entire/cli/auth"
 14→	"github.com/spf13/cobra"
 15→)
 16→
 17→const fallbackDeviceAuthPollInterval = time.Second
 18→const slowDownBackoff = 5 * time.Second
 19→const maxPollInterval = 30 * time.Second
 20→const maxExpiresIn = 15 * time.Minute
 21→const maxTransientErrors = 5
 22→
 23→// browserOpenFunc is the signature for opening a URL in the user's browser.
 24→type browserOpenFunc func(ctx context.Context, url string) error
 25→
 26→// deviceAuthClient abstracts the auth client so runLogin and waitForApproval can be unit-tested.
 27→type deviceAuthClient interface {
 28→	StartDeviceAuth(ctx context.Context) (*auth.DeviceAuthStart, error)
 29→	PollDeviceAuth(ctx context.Context, deviceCode string) (*auth.DeviceAuthPoll, error)
 30→	BaseURL() string
 31→}
 32→
 33→func newLoginCmd() *cobra.Command {
 34→	var printBrowserURL bool
 35→
 36→	cmd := &cobra.Command{
 37→		Use:   "login",
 38→		Short: "Log in to Entire",
 39→		RunE: func(cmd *cobra.Command, _ []string) error {
 40→			client := auth.NewClient(nil)
 41→			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), client, openBrowser, printBrowserURL)
 42→		},
 43→	}
 44→
 45→	cmd.Flags().BoolVar(&printBrowserURL, "print-browser-url", false, "Print the approval URL instead of opening a browser")
 46→
 47→	return cmd
 48→}
 49→
 50→func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc, printBrowserURL bool) error {
 51→	start, err := client.StartDeviceAuth(ctx)
 52→	if err != nil {
 53→		return fmt.Errorf("start login: %w", err)
 54→	}
 55→
 56→	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
 57→	approvalURL := start.VerificationURIComplete
 58→	if approvalURL == "" {
 59→		approvalURL = start.VerificationURI
 60→	}
 61→
 62→	fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
 63→
 64→	if printBrowserURL {
 65→		fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 66→	} else {
 67→		if err := openURL(ctx, approvalURL); err != nil {
 68→			fmt.Fprintf(errW, "Warning: failed to open browser automatically: %v\n", err)
 69→			fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 70→		} else {
 71→			fmt.Fprintln(outW, "Opened your browser for approval.")
 72→		}
 73→	}
 74→
 75→	fmt.Fprintln(outW, "Waiting for approval...")
 76→
 77→	token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, start.Interval)
 78→	if err != nil {
 79→		return fmt.Errorf("complete login: %w", err)
 80→	}
 81→
 82→	store := auth.NewStore()
 83→
 84→	if err := store.SaveToken(client.BaseURL(), token); err != nil {
 85→		return fmt.Errorf("save auth token: %w", err)
 86→	}
 87→
 88→	fmt.Fprintln(outW, "Login complete.")
 89→	return nil
 90→}
 91→
 92→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
 93→	expiry := time.Duration(expiresIn) * time.Second
 94→	if expiry <= 0 || expiry > maxExpiresIn {
 95→		expiry = maxExpiresIn
 96→	}
 97→	deadline := time.Now().Add(expiry)
 98→	pollInterval := time.Duration(interval) * time.Second
 99→	if pollInterval <= 0 {
100→		pollInterval = fallbackDeviceAuthPollInterval
101→	}
102→
103→	consecutiveErrors := 0
104→
105→	for {
106→		if time.Now().After(deadline) {
107→			return "", errors.New("device authorization expired")
108→		}
109→
110→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
111→		if err != nil {
112→			consecutiveErrors++
113→			if consecutiveErrors >= maxTransientErrors {
114→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
115→			}
116→			// Transient error — wait and retry.
117→			select {
118→			case <-ctx.Done():
119→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
120→			case <-time.After(pollInterval):
121→			}
122→			continue
123→		}
124→		consecutiveErrors = 0
125→
126→		switch result.Error {
127→		case "", "authorization_pending":
128→			// continue below
129→		case "slow_down":
130→			pollInterval += slowDownBackoff
131→			if pollInterval > maxPollInterval {
132→				pollInterval = maxPollInterval
133→			}
134→		case "access_denied":
135→			return "", errors.New("device authorization denied")
136→		case "expired_token":
137→			return "", errors.New("device authorization expired")
138→		default:
139→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
140→		}
141→
142→		if result.Error == "" {
143→			if result.AccessToken == "" {
144→				return "", errors.New("device authorization completed without a token")
145→			}
146→			return result.AccessToken, nil
147→		}
148→
149→		select {
150→		case <-ctx.Done():
151→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
152→		case <-time.After(pollInterval):
153→		}
154→	}
155→}
156→
157→func openBrowser(ctx context.Context, browserURL string) error {
158→	u, err := url.Parse(browserURL)
159→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
160→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
161→	}
162→
163→	var command string
164→	var args []string
165→
166→	switch runtime.GOOS {
167→	case "darwin":
168→		command = "open"
169→		args = []string{browserURL}
170→	case "linux":
171→		command = "xdg-open"
172→		args = []string{browserURL}
173→	case "windows":
174→		command = "cmd"
175→		args = []string{"/c", "start", "", browserURL}
176→	default:
177→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
178→	}
179→
180→	cmd := exec.CommandContext(ctx, command, args...)
181→	if err := cmd.Start(); err != nil {
182→		return fmt.Errorf("start browser command %q: %w", command, err)
183→	}
184→
185→	if err := cmd.Process.Release(); err != nil {
186→		return fmt.Errorf("release browser process: %w", err)
187→	}
188→
189→	return nil
190→}
